for m in commissioning_admission commissioning_apply commissioning_capture commissioning_coordinator commissioning_evidence commissioning_evidence_store commissioning_host commissioning_isolated_producer commissioning_lifecycle commissioning_receipt commissioning_run commissioning_runtime commissioning_service commissioning_verification commission_ramp commission_wiring camilla_yaml runtime_contract startup_load startup_hold staging profile baseline_profile passive_profile revalidation reset restore_wait setup_status web_commissioning web_measurement wizard_client tuning_handoff volume_latch session_volume_plan playback playback_route safe_playback program_playback path_safety driver_safety driver_protection graph_safety excitation_safety_plan bringup bundles environment _common; do
  prod=$(grep -rlE "active_speaker[. ]*import +.*\b$m\b|active_speaker\.$m\b|from \.$m import|from \. import .*\b$m\b" --include='*.py' jasper/ scripts/ deploy/ experiments/ rust/ 2>/dev/null | grep -v "/active_speaker/$m.py" | wc -l)
  prodlist=$(grep -rlE "active_speaker[. ]*import +.*\b$m\b|active_speaker\.$m\b|from \.$m import|from \. import .*\b$m\b" --include='*.py' jasper/ scripts/ deploy/ experiments/ 2>/dev/null | grep -v "/active_speaker/$m.py" | sed 's|.*/||' | tr '\n' ',' )
  tst=$(grep -rlE "active_speaker[. ]*import +.*\b$m\b|active_speaker\.$m\b" --include='*.py' tests/ 2>/dev/null | wc -l)
  printf "%-38s prod=%-3s tests=%-4s %s\n" "$m" "$prod" "$tst" "$prodlist"
done
